corrected_code:
const express = require('express');
const { UserLifecycleStore, TenantSecurityConfig } = require('../services/lifecycle');

const app = express();
app.use(express.json());

app.post('/api/okta/webhooks/user-lifecycle', async (req, res) => {
  const authHeader = req.headers['authorization'];
  const { eventType, targetUserExternalId, customerTenantId } = req.body;

  if (!customerTenantId || !targetUserExternalId) {
    return res.status(400).json({ error: 'Missing mandatory hook parameters' });
  }

  // Validate authorization token against the specific tenant's registered Okta shared secret
  const tenantConfig = await TenantSecurityConfig.findByTenantId(customerTenantId);
  if (!tenantConfig || authHeader !== `Bearer ${tenantConfig.oktaWebhookToken}`) {
    return res.status(401).json({ error: 'Unauthorized Okta webhook request' });
  }

  if (eventType !== 'user.lifecycle.suspend') {
    return res.status(200).json({ ignored: true });
  }

  await UserLifecycleStore.suspendUserInTenant(customerTenantId, targetUserExternalId);

  res.json({ success: true, suspended: targetUserExternalId });
});

app.listen(9002);
